add_filter( 'woocommerce_empty_price_html', 'perfectpixel_call_for_price', 10, 2 );

function perfectpixel_call_for_price( $html, $product ) {
	$html = '<span class="perfectpixel-poa">' . esc_html( '{{poa_text}}' ) . '</span>';
	if ( is_product() && get_the_ID() === $product->get_id() ) {
		$link = '{{poa_link}}';
		if ( 0 === strpos( $link, '/' ) ) {
			$link = home_url( $link );
		}
		$link  = add_query_arg( 'product', rawurlencode( $product->get_name() ), $link );
		$html .= ' <a class="button perfectpixel-poa-button" href="' . esc_url( $link ) . '">' . esc_html( '{{poa_button}}' ) . '</a>';
	}
	return $html;
}
